"""BAT-02 batch job error-handling runner."""

from typing import Any, Callable


def run_jobs(jobs: list[dict], executor: Callable[[dict], Any]) -> list[dict]:
    """Run scheduled jobs sequentially using their legacy error policies."""
    run_log: list[dict] = []

    for job in jobs:
        policy = job["on_error"]["policy"]

        if policy == "RETRY":
            attempts = 0
            max_attempts = job["on_error"]["retries"] + 1

            while attempts < max_attempts:
                attempts += 1
                try:
                    executor(job)
                except Exception:
                    if attempts == max_attempts:
                        run_log.append(
                            {
                                "name": job["name"],
                                "attempts": attempts,
                                "outcome": "abort",
                                "audits": [],
                            }
                        )
                        return run_log
                else:
                    run_log.append(
                        {
                            "name": job["name"],
                            "attempts": attempts,
                            "outcome": "ok",
                            "audits": [],
                        }
                    )
                    break
            continue

        try:
            executor(job)
        except Exception:
            if policy == "CONTINUE":
                run_log.append(
                    {
                        "name": job["name"],
                        "attempts": 1,
                        "outcome": "skip",
                        "audits": ["BATCH_ROWSKIP"],
                    }
                )
                continue

            run_log.append(
                {
                    "name": job["name"],
                    "attempts": 1,
                    "outcome": "abort",
                    "audits": [],
                }
            )
            return run_log

        run_log.append(
            {
                "name": job["name"],
                "attempts": 1,
                "outcome": "ok",
                "audits": [],
            }
        )

    return run_log
